      "summary_ja": "若手研究の公募情報は、基盤研究（Ａ・Ｂ・Ｃ）・挑戦的研究と共通の公募ページに掲載されています。令和9（2027）年度分は公募中で、2026-09-17 16:30 JST が JSPS 締切です。公募要領、審査区分表、S-21、入力要領を同じ公式ページで確認できます。",
      "summary_zh": "“青年研究（若手研究）”的公募信息发布在基盘研究（A/B/C）・挑战性研究・若手研究的共用官方页面上。令和9（2027）年度项目正在公募，JSPS 截止时间为 2026-09-17 16:30 JST；公募要领、审查区分表、S-21 和填写指南均可在该官方页面核对。",
      "summary_en": "The call information for Early-Career Scientists is published on the shared official page for Scientific Research (A/B/C), Challenging Research, and Early-Career Scientists. The FY2027 call is open, with a JSPS deadline of 2026-09-17 16:30 JST; the official page also provides the procedures, review table, S-21, and preparation guidance.",
      "eligibility_ja": "若手研究を準備する場合は、この共通ページで公募要領、審査区分表、S-21、Web入力要領、研究計画調書の全体イメージをまとめて確認します。",
      "eligibility_zh": "准备“青年研究（若手研究）”时，应优先在这个共用页面核对公募要领、审查区分表、S-21、Web 输入要领以及研究计划书整体样例。",
      "eligibility_en": "Use this shared page to confirm the application procedures, the review section table, the S-21 form family, the web-entry guidance, and the full proposal-image samples for Early-Career Scientists.",
