        "令和9（2027）年度若手研究の公募期間は 2026-07-14 から 2026-09-17 16:30 JST までです。科研費電子申請システムは 2026-07-22 から利用できます。",
        "共通ページでは、S-21、添付ファイル項目の作成・記入要領、審査区分表、研究計画調書の全体イメージが特に重要です。",
        "公式ページには 2026-07-31 付のシステム不具合通知と解消状況も掲載されているため、提出前に最新通知と学内締切を再確認してください。"
