      "summary_ja": "令和8（2026）年度の公募は 2026-05-08 16:30 JST に終了し、現在は次回準備のための公式参照ページです。専用ページには、公募期間、電子申請システムの利用開始日、S-22、日英の公募要領・作成要領、FAQ への主要導線がまとまっています。",
      "summary_zh": "令和8（2026）年度公募已于 2026-05-08 16:30 JST 结束，当前页面作为下一轮准备的官方参考入口。专页集中提供公募期间、电子申报系统开放时间、S-22、日英公募要领与填写指南，以及 FAQ 入口。",
      "summary_en": "The FY2026 call closed on 2026-05-08 16:30 JST and the page now serves as the official reference for the next cycle. It consolidates the call period, electronic-system opening date, S-22 forms, Japanese and English procedures and preparation guidance, and the main FAQ links.",
      "eligibility_ja": "新たに研究機関へ採用された研究者や、育児休業等を経て研究を再開する研究者を主な対象とする種目です。学内締切、e-Rad 上の応募資格、S-22 の準備状況を早めに確認してください。",
      "eligibility_zh": "该项目主要面向新任教员，以及经历育儿休假等研究中断后重新启动研究的申请者。请尽早核对校内截止、e-Rad 応募资格以及 S-22 套件准备情况。",
      "eligibility_en": "This program mainly targets newly appointed researchers and applicants restarting research after interruptions such as childcare leave. Confirm your institutional deadline, e-Rad eligibility, and S-22 preparation status as early as possible.",
      "watchpoints_ja": [
        "令和8（2026）年度研究活動スタート支援は 2026-05-08 16:30 JST に公募を終了し、公式ページも参考掲載へ切り替わっています。",
        "次回公募に備え、e-Rad の応募資格、学内締切、S-22 の準備条件を早めに確認してください。",
        "現行の公式ページでは、日英の公募要領、Web入力要領、S-22 Word・PDF、添付ファイル作成要領をすべて取得できます。"
      ],
      "watchpoints_zh": [
        "令和8（2026）年度研究活动启动支援已于 2026-05-08 16:30 JST 截止，官方页面现已转为参考资料。",
        "为下一轮做准备时，应尽早核对 e-Rad 申请资格、校内截止与 S-22 准备条件。",
        "当前官方页面已提供日英公募要领、Web 输入指南、S-22 Word／PDF 以及附件文件填写指南。"
      ],
      "watchpoints_en": [
        "The FY2026 Research Activity Start-up Support call closed on 2026-05-08 16:30 JST, and the official page now retains the material for reference.",
        "For the next cycle, confirm e-Rad eligibility, your institutional deadline, and the S-22 preparation requirements early.",
        "The current official page provides the Japanese and English procedures, web-entry guidance, S-22 Word and PDF forms, and uploaded-file preparation guidance."
      ],
