      "summary_ja": "国際共同研究加速基金（国際共同研究強化）の公式公募ページです。現在の公募要領、主要様式、FAQ への導線を 1 か所で確認できます。",
      "summary_zh": "这是 国际共同研究加速基金（国际共同研究强化） 的官方公募页，可在这里集中核对当前公募要领、主要样式与 FAQ 入口。",
      "summary_en": "This is the official call page for Fund for the Promotion of Joint International Research (Fostering Joint International Research), bringing together the current application procedures, core forms, and FAQ routes.",
      "eligibility_ja": "国際共同研究加速基金（国際共同研究強化）を確認するときは、公募要領、関連 FAQ、主要様式（S-61）をあわせて見ておくと全体像を掴みやすくなります。",
      "eligibility_zh": "整理 国际共同研究加速基金（国际共同研究强化） 时，建议把公募要领、相关 FAQ 与主要样式（S-61）放在一起核对。",
      "eligibility_en": "When reviewing Fund for the Promotion of Joint International Research (Fostering Joint International Research), it is best to keep the application procedures, the related FAQ, and the main forms (S-61) side by side.",
      "watchpoints_ja": [
        "国際共同研究加速基金（国際共同研究強化）は 2026-07-14 から 2026-09-17 16:30 JST までの公募期間が設定されており、現在は 公募中 として確認できます。",
        "電子申請システムの利用開始日は 2026-07-22 と案内されています。e-Rad や学内締切の確認も並行して進めてください。",
        "主要様式として S-61 を確認できます。作成要領や PDF 版も同じページから追えるかを必ず確認してください。",
        "制度全体の構成や過年度資料を見返すときは、対応する種目ページもあわせて確認すると整理しやすくなります。"
      ],
