      "summary_ja": "国際共同研究加速基金（海外連携研究）の現行ページは今回分の公募を終えていますが、次回準備に向けて公募要領、主要様式、関連 FAQ を確認する基準ページとして使えます。",
      "summary_zh": "国际共同研究加速基金（海外联携研究） 当前这一轮已结束，但该页仍是下一轮准备时核对公募要领、主要样式与 FAQ 的官方基准页。",
